{
  "message": "I can help with that. Do you want me to submit the credit limit increase request on your behalf, or would you prefer step-by-step instructions so you can submit it yourself?",
  "notes": {
    "eligibility_summary": [
      "Card tier: Gold Rewards Card = Premium tier.",
      "Payment history: typically requires 3 consecutive months of on-time payments.",
      "Maximum increase per request: up to 50% of your current credit limit.",
      "Other requirements: account must be in good standing (no past-due balance), no active disputes, no pending replacement cards, and cooldown-period checks may apply."
    ],
    "what_i_need_to_submit_for_you": [
      "Tell me whether you want a dollar amount increase (e.g., +$5,000) or a new total credit limit (e.g., $20,000).",
      "A brief reason (you already mentioned home renovation — that works).",
      "Confirmation you are the account owner or authorized manager for this card."
    ],
    "identity_verification": "If you want me to submit the request for you, I must verify your identity first. Please be prepared to provide any 2 of the following: date of birth, email on file, phone number on file, or mailing address. After verification I will log the verification in our records.",
    "timeline": "You’ll typically receive a decision by email within a few business days. If approved, the new limit takes effect once processed and will appear in your account.",
    "next_steps_prompt": "Would you like me to: (A) proceed and submit the request for you (if so, please tell me which 2 identity fields you’ll provide and the requested increase/new total), or (B) give step-by-step instructions to submit via the app or phone?"
  }
}
